'use strict';
const fs=require('node:fs'),path=require('node:path'),http=require('node:http');
const root=path.resolve(process.env.MATCHAPP_QA_ROOT||path.join(__dirname,'..'));
const {chromium}=require(root+'/node_modules/playwright');
const out=path.resolve(process.env.MATCHAPP_QA_OUTPUT||path.join(root,'reports/android-ui-20261021/rendering'));fs.mkdirSync(out,{recursive:true});
const mime={'.html':'text/html','.css':'text/css','.js':'application/javascript','.json':'application/json','.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg','.webp':'image/webp','.avif':'image/avif'};
const server=http.createServer((req,res)=>{try{let f=path.resolve(root,'.'+decodeURIComponent(new URL(req.url,'http://localhost').pathname));if(f!==root&&!f.startsWith(root+'/'))throw Error('outside');if(fs.statSync(f).isDirectory())f=path.join(f,'index.html');res.setHeader('Content-Type',mime[path.extname(f)]||'application/octet-stream');fs.createReadStream(f).pipe(res);}catch{res.writeHead(404).end();}});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});const report={scope:'Local candidate geometry and original-image resolution; external services blocked. This is not field performance or a physical 12K display test.',cases:[]};
try{for(const [width,dpr] of [[390,1],[390,3],[800,1.5],[1366,2],[3840,1],[12288,1]]){const context=await browser.newContext({viewport:{width,height:1000},deviceScaleFactor:dpr,reducedMotion:'reduce'});await context.addInitScript(()=>{localStorage.setItem('match_cookie_choice','essential');localStorage.setItem('match_lang','en');localStorage.setItem('match_settings',JSON.stringify({reduceMotion:true}));});await context.route(/^https?:\/\/(?!127\.0\.0\.1)/,r=>r.abort());const page=await context.newPage();for(const route of ['/','/explore.html']){const response=await page.goto('http://127.0.0.1:'+server.address().port+route,{waitUntil:'domcontentloaded'});if(response.status()!==200)throw Error('Failed route '+route+': '+response.status());await page.waitForTimeout(1600);const result=await page.evaluate(()=>{const visible=e=>{const r=e.getBoundingClientRect();return r.width&&r.height&&r.right>0&&r.left<innerWidth&&r.bottom>0&&r.top<innerHeight&&e.checkVisibility({checkOpacity:true,checkVisibilityCSS:true});};const images=[...document.images].filter(visible).map(e=>({id:e.id,src:e.currentSrc||e.src,srcset:e.srcset,rendered:{w:e.getBoundingClientRect().width,h:e.getBoundingClientRect().height},natural:{w:e.naturalWidth,h:e.naturalHeight},fit:getComputedStyle(e).objectFit,decoded:e.complete&&e.naturalWidth>0}));const backgrounds=[...document.querySelectorAll('.home-hero,.ref-explore-hero,.ref-editorial-banner,.ref-topic')].filter(visible).map(e=>({class:e.className,rect:e.getBoundingClientRect().toJSON(),source:getComputedStyle(e).backgroundImage,fit:getComputedStyle(e).backgroundSize}));return {viewport:{width:innerWidth,height:innerHeight,dpr:devicePixelRatio},overflow:document.documentElement.scrollWidth-innerWidth,images,backgrounds,resources:performance.getEntriesByType('resource').filter(e=>e.name.includes('/assets/cinema/')||e.name.includes('/jonas/faces/')).map(e=>({url:e.name,duration:e.duration,transfer:e.transferSize,start:e.startTime}))};});report.cases.push({route,...result});console.log(JSON.stringify({route,width,dpr,overflow:result.overflow,images:result.images.length}));}await context.close();}}finally{await browser.close();server.close();fs.writeFileSync(out+'/source-quality.json',JSON.stringify(report,null,2));}})().catch(e=>{console.error(e);process.exitCode=1;server.close();});
